"""Swagger/ReDoc documentation generated by drf-yasg."""

from django.urls import path, re_path
from drf_yasg import openapi
from drf_yasg.views import get_schema_view
from rest_framework.permissions import AllowAny

schema_view = get_schema_view(
    openapi.Info(
        title="Task Management API",
        default_version="v1",
        description=(
            "REST API for creating, assigning, completing and filtering tasks.\n\n"
            "Log in at `/api/auth/login/`, then click **Authorize** and enter "
            "`Bearer <access token>`. Request and response bodies use camelCase; "
            "query parameters use snake_case."
        ),
    ),
    public=True,
    permission_classes=[AllowAny],
)

urlpatterns = [
    re_path(
        r"^swagger\.(?P<format>json|yaml)$",
        schema_view.without_ui(cache_timeout=0),
        name="schema-json",
    ),
    path("docs/", schema_view.with_ui("swagger", cache_timeout=0), name="schema-swagger-ui"),
    path("redoc/", schema_view.with_ui("redoc", cache_timeout=0), name="schema-redoc"),
]
